//@ run-pass
//@ expect-stdout: GRESNIGT OK
// FRENTE B, vector 4/3 — cross-check of Gresnigt's three generation-octonions + an explicit G₂
// (COLOR-side) monomial automorphism permuting them. Executed against the primary source.
//
// Gresnigt (EPJC 2019/2024; arXiv:2306.13098) builds three fermion generations from three octonion
// subalgebras of the sedenions 𝕊 sharing a common quaternion, cyclically related by the family S₃.
// The paper's three copies (its basis, App. A) are, as index sets:
//   𝕆₁ = {1,4,5,8,9,12,13},  𝕆₂ = {2,4,6,8,10,12,14},  𝕆₃ = {3,4,7,8,11,12,15},
//   sharing the quaternion ℍ = ⟨e₄,e₈,e₁₂⟩ = {4,8,12}.
// This test certifies, in this repo's Cayley-Dickson convention:
//   (a) each 𝕆_i is a genuine (zero-divisor-free) octonion, all three ambient-equivalent (each has 6
//       non-anticommuting internal left-mult pairs in the 16-dim Cℓ(8));  ℍ = 𝕆₁∩𝕆₂∩𝕆₃ = {4,8,12};
//   (b) the pure 3-cycle φ = (e₁e₂e₃)(e₅e₆e₇)(e₉e₁₀e₁₁)(e₁₃e₁₄e₁₅) [all signs +1, fixing e₀,e₄,e₈,e₁₂]
//       is a genuine algebra automorphism of 𝕊 (all 256 products), of order 3, cyclically permuting
//       𝕆₁→𝕆₂→𝕆₃ and fixing ℍ and e₈;
//   (c) φ = g ⊕ g is DIAGONAL under 𝕊 = 𝕆 ⊕ 𝕆·e₈ with g = (e₁e₂e₃)(e₅e₆e₇) an automorphism of the base
//       octonion {e₁..e₇} — so φ ∈ G₂ = Aut(𝕆).
//
// HONEST BOUNDARY (this is NOT a physics bridge). Because φ ∈ G₂ and G₂ ⊃ SU(3)_color, φ is a
// COLOR-sector operation. It is NOT Gresnigt's family S₃: by Brown's theorem Aut(𝕊)=G₂×S₃, and the
// family S₃ is precisely the direct factor DISJOINT from G₂ (non-monomial) — used exactly so that
// family ≠ color. This brick therefore does NOT connect the zero-divisor monomial-168 to fermion
// generations, and does NOT amend Erratum E1 (which correctly places the monomial-168 inside G₂). It
// reproduces the paper's octonion triple and exhibits the G₂/color realization of their 3-set
// permutation — nothing more. A genuine bridge would require building the fermion ideals and showing
// Brown's S₃ acts on those states as a monomial-168 element; that is not done here.
//
// Decidable integer arithmetic, no float. SELF-CONTAINED. Cross-verified vs the oracle by the gate + Lean.

fn cd_sigma_c(a: i64, b: i64, bits: i64) -> i64 with Mut, Panic, Div {
    if a == 0 || b == 0 { return 1 }
    if bits <= 1 { return 0 - 1 }
    let half = 1 << (bits - 1)
    let a_hi = if a >= half { 1 } else { 0 }
    let b_hi = if b >= half { 1 } else { 0 }
    let a_lo = a & (half - 1)
    let b_lo = b & (half - 1)
    if a_hi == 0 && b_hi == 0 { return cd_sigma_c(a_lo, b_lo, bits - 1) }
    if a_hi == 0 && b_hi == 1 { return cd_sigma_c(b_lo, a_lo, bits - 1) }
    if a_hi == 1 && b_hi == 0 {
        if b_lo == 0 { return cd_sigma_c(a_lo, 0, bits - 1) }
        return 0 - cd_sigma_c(a_lo, b_lo, bits - 1)
    }
    if b_lo == 0 { return 0 - cd_sigma_c(0, a_lo, bits - 1) }
    cd_sigma_c(b_lo, a_lo, bits - 1)
}
fn sg(a: i64, b: i64) -> i64 with Mut, Panic, Div { cd_sigma_c(a, b, 4) }
fn antiL(i: i64, j: i64) -> bool with Mut, Panic, Div {
    var c = 0
    while c < 16 {
        if sg(i, j ^ c) * sg(j, c) + sg(j, i ^ c) * sg(i, c) != 0 { return false }
        c = c + 1
    }
    true
}
fn pprod(ulo: i64, uhi: i64, us: i64, vlo: i64, vhi: i64, vs: i64, k: i64) -> i64 with Mut, Panic, Div {
    var acc = 0
    if (ulo ^ vlo) == k { acc = acc + sg(ulo, vlo) }
    if (ulo ^ vhi) == k { acc = acc + vs * sg(ulo, vhi) }
    if (uhi ^ vlo) == k { acc = acc + us * sg(uhi, vlo) }
    if (uhi ^ vhi) == k { acc = acc + us * vs * sg(uhi, vhi) }
    acc
}
fn zero_pair(ulo: i64, uhi: i64, us: i64, vlo: i64, vhi: i64, vs: i64) -> bool with Mut, Panic, Div {
    var k = 0
    while k < 16 {
        if pprod(ulo, uhi, us, vlo, vhi, vs, k) != 0 { return false }
        k = k + 1
    }
    true
}
fn oct_zdfree_and_nonanti6(u0: i64, u1: i64, u2: i64, u3: i64, u4: i64, u5: i64, u6: i64) -> bool with Mut, Panic, Div {
    var u = [0; 7]
    u[0 as usize] = u0
    u[1 as usize] = u1
    u[2 as usize] = u2
    u[3 as usize] = u3
    u[4 as usize] = u4
    u[5 as usize] = u5
    u[6 as usize] = u6
    // ZD-free: no annihilating primitive pair
    var a = 0
    while a < 7 {
        var b = a + 1
        while b < 7 {
            var us = 0 - 1
            while us <= 1 {
                if us != 0 {
                    var cc = 0
                    while cc < 7 {
                        var dd = cc + 1
                        while dd < 7 {
                            var vs = 0 - 1
                            while vs <= 1 {
                                if vs != 0 {
                                    if zero_pair(u[a as usize], u[b as usize], us, u[cc as usize], u[dd as usize], vs) {
                                        return false
                                    }
                                }
                                vs = vs + 1
                            }
                            dd = dd + 1
                        }
                        cc = cc + 1
                    }
                }
                us = us + 1
            }
            b = b + 1
        }
        a = a + 1
    }
    // nonanti == 6
    var non = 0
    a = 0
    while a < 7 {
        var b = a + 1
        while b < 7 {
            if !antiL(u[a as usize], u[b as usize]) { non = non + 1 }
            b = b + 1
        }
        a = a + 1
    }
    non == 6
}

fn main() with IO, Mut, Panic, Div {
    // the 3-cycle phi (all signs +1): index permutation
    var pi = [0; 16]
    pi[0 as usize] = 0
    pi[1 as usize] = 2
    pi[2 as usize] = 3
    pi[3 as usize] = 1
    pi[4 as usize] = 4
    pi[5 as usize] = 6
    pi[6 as usize] = 7
    pi[7 as usize] = 5
    pi[8 as usize] = 8
    pi[9 as usize] = 10
    pi[10 as usize] = 11
    pi[11 as usize] = 9
    pi[12 as usize] = 12
    pi[13 as usize] = 14
    pi[14 as usize] = 15
    pi[15 as usize] = 13

    // (b) phi is an algebra automorphism (all 256 products): sign-free monomial condition
    //     sg(pi i, pi j) == sg(i,j)  AND  pi(i^j) == pi(i)^pi(j).
    var aut_ok = 1
    var i = 0
    while i < 16 {
        var j = 0
        while j < 16 {
            if sg(pi[i as usize], pi[j as usize]) != sg(i, j) { aut_ok = 0 }
            if pi[(i ^ j) as usize] != (pi[i as usize] ^ pi[j as usize]) { aut_ok = 0 }
            j = j + 1
        }
        i = i + 1
    }
    // order 3
    var ord3 = 1
    var moved = 0
    i = 0
    while i < 16 {
        if pi[pi[pi[i as usize] as usize] as usize] != i { ord3 = 0 }
        if pi[i as usize] != i { moved = 1 }
        i = i + 1
    }
    // fixes e8 and the quaternion {4,8,12}
    var fixes = 1
    if pi[8 as usize] != 8 { fixes = 0 }
    if pi[4 as usize] != 4 { fixes = 0 }
    if pi[12 as usize] != 12 { fixes = 0 }
    // (c) g in G2: phi preserves the base octonion {1..7}, and there g is an octonion automorphism.
    var g2 = 1
    i = 1
    while i <= 7 {
        if pi[i as usize] < 1 || pi[i as usize] > 7 { g2 = 0 }
        i = i + 1
    }
    // g = phi|{1..7} is an automorphism of O (octonion sigma bits=3)
    i = 0
    while i < 8 {
        var j = 0
        while j < 8 {
            if cd_sigma_c(pi[i as usize], pi[j as usize], 3) != cd_sigma_c(i, j, 3) { g2 = 0 }
            j = j + 1
        }
        i = i + 1
    }

    // (a) each O_i is a ZD-free octonion with nonanti==6
    let o1 = oct_zdfree_and_nonanti6(1, 4, 5, 8, 9, 12, 13)
    let o2 = oct_zdfree_and_nonanti6(2, 4, 6, 8, 10, 12, 14)
    let o3 = oct_zdfree_and_nonanti6(3, 4, 7, 8, 11, 12, 15)
    var octs_ok = 0
    if o1 && o2 && o3 { octs_ok = 1 }
    // phi cycles O1 -> O2 -> O3 (setwise, via membership masks)
    var m1 = 0
    var m2 = 0
    var m3 = 0
    m1 = (1<<1)|(1<<4)|(1<<5)|(1<<8)|(1<<9)|(1<<12)|(1<<13)
    m2 = (1<<2)|(1<<4)|(1<<6)|(1<<8)|(1<<10)|(1<<12)|(1<<14)
    m3 = (1<<3)|(1<<4)|(1<<7)|(1<<8)|(1<<11)|(1<<12)|(1<<15)
    // image of a mask under pi
    var im1 = 0
    var im2 = 0
    var b = 1
    while b <= 15 {
        if (m1 & (1 << b)) != 0 { im1 = im1 | (1 << pi[b as usize]) }
        if (m2 & (1 << b)) != 0 { im2 = im2 | (1 << pi[b as usize]) }
        b = b + 1
    }
    var cyc_ok = 0
    if im1 == m2 && im2 == m3 { cyc_ok = 1 }

    print("AUT_OK ")
    print_int(aut_ok as i64)
    print("\n")
    print("ORD3 ")
    print_int((ord3 & moved) as i64)
    print("\n")
    print("FIX_QH_E8 ")
    print_int(fixes as i64)
    print("\n")
    print("G2_DIAGONAL ")
    print_int(g2 as i64)
    print("\n")
    print("OCTS_ZDFREE_NA6 ")
    print_int(octs_ok as i64)
    print("\n")
    print("CYCLE_O1O2O3 ")
    print_int(cyc_ok as i64)
    print("\n")
    // Gresnigt's octonion triple reproduced; phi is a G₂ (color-side) monomial automorphism cycling
    // them. NOT the family S₃ (Brown factor, non-monomial). NOT a bridge. E1 stands.
    if aut_ok == 1 && ord3 == 1 && moved == 1 && fixes == 1 && g2 == 1 && octs_ok == 1 && cyc_ok == 1 {
        println("GRESNIGT OK")
    } else {
        println("GRESNIGT FAIL")
    }
}

//@ run-pass
//@ expect-stdout-contains: ON-LOCUS E=0 Var=0 PASS
//@ expect-stdout-contains: OFF-LOCUS E=0 Var>0 PASS
//@ expect-stdout-contains: EXACT-MEASURE-ANNIHILATION PASS
// EXACT measure-layer Structural Annihilation (Frente A: the SECOND half, over Q).
//
// The ZD census (over Z) certified the annihilation LOCUS. This certifies the MEASURE claim on it,
// exactly over Q -- the exact analogue of the float "confidence collapse" in sedenion_zero_divisor.sio.
//
// Object (from that float witness): a = alpha*e3 + beta*e10, b = gamma*e6 + delta*e15.
// The e5 and e12 components of a*b are  r5 = alpha*gamma + beta*delta,  r12 = alpha*delta + beta*gamma.
// The locus is { (alpha,beta,gamma,delta) : r5 = r12 = 0 } (e.g. (t,t,s,-s) for any t,s).
//
// Claim executed here, by DECIDABLE RATIONAL equality (no tolerance):
//   * measure supported EXACTLY on the locus  ->  E[r] = 0/1  AND  Var[r] = 0/1   (exact zero)
//   * measure perturbed OFF the locus (exact rational eps)  ->  E[r] = 0/1  BUT  Var[r] > 0 exactly.
// float Var>0 was the number; exact Var = 0/1 vs 1/150 is the contract.
//
// Self-contained inline rationals (num/den, i64). NB: i64-bounded (issue: no bigint) -- fine for these
// small denominators; a general measure needs overflow-checked / bigint rationals (rational.sio's guards).

fn igcd(a: i64, b: i64) -> i64 with Mut, Panic, Div {
    var x = if a < 0 { 0 - a } else { a }
    var y = if b < 0 { 0 - b } else { b }
    while y != 0 {
        let t = x - (x / y) * y   // x mod y
        x = y
        y = t
    }
    if x == 0 { 1 } else { x }
}

struct Rat { n: i64, d: i64 }

// Normalize: den > 0, gcd(|n|,d) = 1.
fn rat_make(n: i64, d: i64) -> Rat with Mut, Panic, Div {
    var nn = n
    var dd = d
    if dd < 0 { nn = 0 - nn; dd = 0 - dd }
    let g = igcd(nn, dd)
    Rat { n: nn / g, d: dd / g }
}
fn rat_add(a: Rat, b: Rat) -> Rat with Mut, Panic, Div { rat_make(a.n * b.d + b.n * a.d, a.d * b.d) }
fn rat_sub(a: Rat, b: Rat) -> Rat with Mut, Panic, Div { rat_make(a.n * b.d - b.n * a.d, a.d * b.d) }
fn rat_mul(a: Rat, b: Rat) -> Rat with Mut, Panic, Div { rat_make(a.n * b.n, a.d * b.d) }
fn rat_is_zero(a: Rat) -> bool { a.n == 0 }
fn rat_eq(a: Rat, b: Rat) -> bool { a.n == b.n && a.d == b.d }

// Product component r5 = alpha*gamma + beta*delta, exactly over Q.
fn r5(al: Rat, be: Rat, ga: Rat, de: Rat) -> Rat with Mut, Panic, Div {
    rat_add(rat_mul(al, ga), rat_mul(be, de))
}

// Empirical measure over N equal-weight sample points held in fixed arrays (num/den, one entry
// per sample per coefficient). E[r] = (sum r_i)/N ; Var[r] = (sum r_i^2)/N - E^2, exact.
// Returns nothing; prints the exact E and Var and a PASS/FAIL against expected.
fn run_case(
    tag: i64,          // 0 = on-locus, 1 = off-locus
    n: i64,
    a_n: [i64; 8], a_d: [i64; 8],
    b_n: [i64; 8], b_d: [i64; 8],
    g_n: [i64; 8], g_d: [i64; 8],
    d_n: [i64; 8], d_d: [i64; 8]
) -> bool with Mut, Panic, IO, Div {
    var sum = Rat { n: 0, d: 1 }
    var sumsq = Rat { n: 0, d: 1 }
    var i = 0
    while i < n {
        let al = rat_make(a_n[i as usize], a_d[i as usize])
        let be = rat_make(b_n[i as usize], b_d[i as usize])
        let ga = rat_make(g_n[i as usize], g_d[i as usize])
        let de = rat_make(d_n[i as usize], d_d[i as usize])
        let ri = r5(al, be, ga, de)
        sum = rat_add(sum, ri)
        sumsq = rat_add(sumsq, rat_mul(ri, ri))
        i = i + 1
    }
    let invN = rat_make(1, n)
    let ev = rat_mul(sum, invN)                       // E[r]
    let e2 = rat_mul(ev, ev)
    let varv = rat_sub(rat_mul(sumsq, invN), e2)       // Var[r] = E[r^2] - E[r]^2
    print("  E[r]  = "); print_int(ev.n); print("/"); print_int(ev.d); print("\n")
    print("  Var[r]= "); print_int(varv.n); print("/"); print_int(varv.d); print("\n")
    // machine-parseable line for the cross-toolchain gate: MEASURE <tag> E <n> <d> VAR <n> <d>
    print("MEASURE ")
    print_int(tag)
    print(" E ")
    print_int(ev.n)
    print(" ")
    print_int(ev.d)
    print(" VAR ")
    print_int(varv.n)
    print(" ")
    print_int(varv.d)
    print("\n")
    // On-locus: E=0 AND Var=0. Off-locus: E=0 AND Var != 0.
    if tag == 0 {
        rat_is_zero(ev) && rat_is_zero(varv)
    } else {
        rat_is_zero(ev) && !rat_is_zero(varv)
    }
}

fn main() with IO, Mut, Panic, Div {
    // CASE 1 -- support EXACTLY on the locus: (t,t,s,-s) has r5 = t*s + t*(-s) = 0 for all t,s.
    // 3 samples: (1,1,1,-1), (2,2,1,-1), (1,1,3,-3). Each: r5 = 0 exactly.
    var a_n = [1, 2, 1, 0, 0, 0, 0, 0]
    var a_d = [1, 1, 1, 1, 1, 1, 1, 1]
    var b_n = [1, 2, 1, 0, 0, 0, 0, 0]
    var b_d = [1, 1, 1, 1, 1, 1, 1, 1]
    var g_n = [1, 1, 3, 0, 0, 0, 0, 0]
    var g_d = [1, 1, 1, 1, 1, 1, 1, 1]
    var d_n = [0 - 1, 0 - 1, 0 - 3, 0, 0, 0, 0, 0]
    var d_d = [1, 1, 1, 1, 1, 1, 1, 1]
    print("CASE on-locus (support in Z, exact):\n")
    let ok1 = run_case(0, 3, a_n, a_d, b_n, b_d, g_n, g_d, d_n, d_d)
    if ok1 { println("  ON-LOCUS E=0 Var=0 PASS") } else { println("  ON-LOCUS FAIL") }

    // CASE 2 -- support perturbed OFF the locus by exact eps = 1/10 on alpha (gamma=1, beta=1, delta=-1):
    // r5 = alpha*1 + 1*(-1) = alpha - 1.  alpha in {9/10, 1, 11/10} -> r5 in {-1/10, 0, 1/10}.
    // E = 0, Var = ((1/10)^2 + 0 + (1/10)^2)/3 = (2/100)/3 = 1/150 (exact positive rational).
    var a2n = [9, 1, 11, 0, 0, 0, 0, 0]
    var a2d = [10, 1, 10, 1, 1, 1, 1, 1]
    var b2n = [1, 1, 1, 0, 0, 0, 0, 0]
    var b2d = [1, 1, 1, 1, 1, 1, 1, 1]
    var g2n = [1, 1, 1, 0, 0, 0, 0, 0]
    var g2d = [1, 1, 1, 1, 1, 1, 1, 1]
    var d2n = [0 - 1, 0 - 1, 0 - 1, 0, 0, 0, 0, 0]
    var d2d = [1, 1, 1, 1, 1, 1, 1, 1]
    print("CASE off-locus (perturbed by eps=1/10, exact):\n")
    let ok2 = run_case(1, 3, a2n, a2d, b2n, b2d, g2n, g2d, d2n, d2d)
    if ok2 { println("  OFF-LOCUS E=0 Var>0 PASS") } else { println("  OFF-LOCUS FAIL") }

    // The exact contract: Var flips from 0/1 (on locus) to 1/150 (off locus) by decidable Q equality.
    if ok1 && ok2 { println("EXACT-MEASURE-ANNIHILATION PASS") } else { println("EXACT-MEASURE-ANNIHILATION FAIL") }
}

//@ run-pass
// Phase 3 demo: the typed epistemic boundary. `Proved` and the measurement variants are distinct;
// `requires_proof` accepts ONLY `Proved` — a measurement can NEVER be laundered into a proof (the
// type system blocks it). This is the load-bearing guarantee of the boundary.
//
// NOTE (souc compiler): `Verdict` is PAYLOAD-FREE here. The intended type carries the tolerance
// (`MeasuredF64 { eps: f64 }`, `MeasuredF256 { eps256: f64 }`) — but the current souc (the stage2
// compiler the CI full-suite builds) rejects data-carrying enum variants: it reports the field name
// as an undefined variable (E200). See docs/handoff/souc_v0800_defects.md (D7). The eps tolerance is
// carried alongside in practice; the boundary guarantee this test certifies (proof vs measurement)
// is unaffected by dropping the payload.

enum Verdict { Proved, MeasuredF64, MeasuredF256 }
fn verdict_proved() -> Verdict { Verdict::Proved }
fn verdict_measured_f64() -> Verdict { Verdict::MeasuredF64 }
fn verdict_measured_f256() -> Verdict { Verdict::MeasuredF256 }
fn requires_proof(v: Verdict) -> bool {
    match v { Verdict::Proved => true, Verdict::MeasuredF64 => false, Verdict::MeasuredF256 => false }
}

fn main() -> i32 with IO, Mut, Panic, Div {
    // requires_proof is the load-bearing boundary: a measurement can NEVER pass as a proof.
    if requires_proof(verdict_proved()) { println("PROOF-ACCEPTED PASS") } else { println("PROOF-ACCEPTED FAIL") }
    if !requires_proof(verdict_measured_f64()) { println("MEASUREMENT-REJECTED PASS") } else { println("MEASUREMENT-REJECTED FAIL") }
    if !requires_proof(verdict_measured_f256()) { println("F256-REJECTED PASS") } else { println("F256-REJECTED FAIL") }
    0
}

